package com.railway.servlet;import jakarta.servlet.*;import jakarta.servlet.http.*;import java.io.IOException;import java.sql.*;import java.util.*;import com.railway.model.User;import com.railway.util.DB;
public class BookingDetailsServlet extends HttpServlet {protected void doGet(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{User u=(User)r.getSession(false).getAttribute("user");String pnr=r.getParameter("pnr");try(Connection c=DB.getConnection();PreparedStatement p=c.prepareStatement("SELECT b.pnr,b.status,b.total_fare,b.passenger_count,sc.journey_date,t.train_name,t.train_number,t.source,t.destination,t.departure_time,t.arrival_time FROM bookings b JOIN train_schedules sc ON sc.id=b.schedule_id JOIN trains t ON t.id=sc.train_id WHERE b.pnr=? AND (b.user_id=? OR ?='ADMIN')")){p.setString(1,pnr==null?"":pnr);p.setLong(2,u.getId());p.setString(3,u.getRole());try(ResultSet x=p.executeQuery()){if(!x.next()){s.sendError(404);return;}Map<String,Object> m=new HashMap<>();for(String k:List.of("pnr","status","total_fare","passenger_count","journey_date","train_name","train_number","source","destination","departure_time","arrival_time"))m.put(k,x.getObject(k));r.setAttribute("booking",m);}}catch(Exception e){getServletContext().log("Booking details failed",e);s.sendError(500);return;}r.getRequestDispatcher("/booking-details.jsp").forward(r,s);}}
